import math


def _is_number(value):
    return not isinstance(value, bool) and isinstance(value, (int, float))


def recurrent_blend(initial, signals, retention):
    if not isinstance(initial, dict):
        raise TypeError("initial must be a dictionary")
    if not initial:
        raise ValueError("initial must be non-empty")

    if not _is_number(retention):
        raise TypeError("retention must be a non-boolean number")
    if not math.isfinite(retention):
        raise ValueError("retention must be finite")
    if not 0 <= retention <= 1:
        raise ValueError("retention out of range")

    state = {}
    for key, vector in initial.items():
        if not isinstance(key, str):
            raise TypeError("initial keys must be strings")
        if not isinstance(vector, list):
            raise TypeError("initial vectors must be lists")
        if not vector:
            raise ValueError("initial vectors must be non-empty")
        for value in vector:
            if not _is_number(value):
                raise TypeError("initial values must be numbers")
            if not math.isfinite(value):
                raise ValueError("initial values must be finite")
        state[key] = list(vector)

    try:
        iterator = iter(signals)
    except TypeError as exc:
        raise TypeError("signals must be iterable") from exc

    snapshots = [state]
    expected_keys = set(state)

    for signal in iterator:
        if not isinstance(signal, dict):
            raise TypeError("each signal must be a dictionary")
        if set(signal) != expected_keys:
            raise ValueError("signal keys differ")

        for key in state:
            vector = signal[key]
            if not isinstance(vector, list):
                raise TypeError("signal vectors must be lists")
            if len(vector) != len(state[key]):
                raise ValueError("signal vector length differs")
            for value in vector:
                if not _is_number(value):
                    raise TypeError("signal values must be numbers")
                if not math.isfinite(value):
                    raise ValueError("signal values must be finite")

        for key in state:
            state[key] = [
                retention * previous + (1 - retention) * current
                for previous, current in zip(state[key], signal[key])
            ]
        snapshots.append(state)

    return snapshots

